class Example {
    void example(boolean refill) {
        byte[] iv = new byte[16]; // Report: default-initialized array.
        new IvParameterSpec(iv); // neither later block has executed yet, still using default-initialized array.
        if (refill) {
            new SecureRandom().nextBytes(iv);
        }
        for (int i = 0; i < iv.length; i++) {
            iv[i] = 1;
        }
    }
}

